package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;public final class IntensityModifierSpec implements ModifierSpec{private final StableId nodeId;private final int numerator,denominator;public IntensityModifierSpec(StableId id,int numerator,int denominator){if(id==null||numerator<1||denominator<1)throw new IllegalArgumentException("invalid intensity modifier");nodeId=id;this.numerator=numerator;this.denominator=denominator;}@Override public StableId nodeId(){return nodeId;}@Override public String variantKey(){return "INTENSITY";}public int numerator(){return numerator;}public int denominator(){return denominator;}}
